// Факты 13.10 (скрины 6a86f7fc-ios-b19-list-no-text-mark.png, 6a86f7fc-ios-b19-reader-no-text.png):
//  AC1 «חזק את חברך» → превью → share sheet — specs/share/sh-01 (SH-02, глава א׳);
//  AC2 «סיים קריאה» → «הקריאה הושלמה», «סיימת את תהילים א׳.» (@data — отметка в аккаунте НЕ убирается; 13.10 клиент уже нажимал на א׳);
//  AC3 заголовок «תהילים א׳» + «אשרי האיש אשר», текст с ניקוד;
//  AC4 пустая глава: в списке label «תהילים ל״ט — אין עדיין טקסט», в главе «לפרק הזה עדיין אין טקסט.» и кнопка «לרשימת הפרקים»;
//  AC5 список «א׳ אשרי האיש אשר», поиск «39» → ל״ט.
// AC4 требует ПОДГОТОВКИ ДАННЫХ на проде (видно всем пользователям!) — по умолчанию тест только проверяет текущее состояние:
//  ל״ט пустая → проверка AC4; ל״ט с текстом → skip с причиной. Подготовка вручную (или QA_ALLOW_TEHILIM39_EMPTY=1 — тест сделает сам):
//   1) аккаунт клиента: профиль → «ממשק ניהול התוכן» → поиск «ל״ט» → «תהילים ל״ט» → קטע «למנצח לידותון מזמור» (до 22.10 — «למנצח לידיתון [לידותון]»);
//   2) очистить «טקסט התפילה» → «שמירת טיוטה» → «אישור ופרסום» (13.10: опубликован пустым 13:05);
//   3) прогнать AC4;
//   4) ⚠ ОБЯЗАТЕЛЬНО ВЕРНУТЬ ТЕКСТ: вставить содержимое .qa/research/6a86f7fca7ea/orig-tehilim-39.txt (2039 байт, с ניקוד) →
//      «שמירת טיוטה» → «אישור ופרסום» → открыть заново и сверить посимвольно (13.10 вернули в 13:08, SHA-256 совпал).
//      Необратимо: записи в «היסטוריית אישורים» и статус утверждения.
//  TH-04e (@prod-safe) после прогона проверяет, что ל״ט снова с текстом и совпадает с оригиналом посимвольно (через админку).
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabelStartsWith, scrollToText, tapText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { openTehilimChapter, typeSearch, shown, skipWith } from '../_lib/app-0710.ts';
import { asAdmin, backToUser1, openAdminHome, setBody, readBody, saveDraft, approveDraft, qaMarker, qaFile } from '../_lib/admin.ts';
import fs from 'node:fs';

const T39_EMPTY_LABEL = 'תהילים ל״ט — אין עדיין טקסט';
const T39_EMPTY_READER = 'לפרק הזה עדיין אין טקסט.';
// ОБНОВЛЕНО 25.10: #56d002bd (#7580ef) עבר QA — имя ל״ט «למנצח לידותון מזמור» (миграция 20261022130000, было «למנצח לידיתון [לידותון]»).
const T39_SECTION = 'למנצח לידותון מזמור';
const origT39 = () => fs.readFileSync(qaFile('research/6a86f7fca7ea/orig-tehilim-39.txt'), 'utf8');

/** Админка → «תהילים ל״ט» → קטע «למנצח לידותון מזמור» («עריכת קטע»). TODO калибровка: склеенная подпись карточки на iOS. */
async function openAdminT39Section() {
  await openAdminHome();
  await typeSearch('ל״ט');
  const card = await byLabelStartsWith('תהילים ל״ט');
  await card.waitForDisplayed({ timeout: 20000 });
  await card.click();
  await (await scrollToText(T39_SECTION)).click();
  await (await byText('עריכת קטע')).waitForDisplayed({ timeout: 20000 });
}

/** В списке «תהילים» после поиска «39»: ל״ט пустая? */
async function t39IsEmptyInList() {
  await toHome();
  await goTab('תהילים');
  await typeSearch('39');
  await (await byTextContains('ל״ט')).waitForDisplayed({ timeout: 20000 });
  return shown(byLabelStartsWith(T39_EMPTY_LABEL));
}

describe('ספריית תהילים (F-52)', () => {
  afterEach(async () => { await toHome(); });

  it('TH-04a AC5 Список: «א׳ אשרי האיש אשר»; поиск «39» → ל״ט #6a86f7fc @prod-safe', async () => {
    await goTab('תהילים');
    await typeSearch('');
    await expect(byTextMatches('(?s).*א׳.*אשרי האיש אשר.*')).toBeDisplayed({ wait: 20000 });
    await typeSearch('39');
    await expect(byTextContains('ל״ט')).toBeDisplayed({ wait: 10000 });
    await expect(byTextMatches('(?s).*א׳.*אשרי האיש אשר.*')).not.toBeDisplayed();
    await typeSearch('');
  });

  it('TH-04b AC3 Глава א׳: заголовок «תהילים א׳», «אשרי האיש אשר», текст с ניקוד #6a86f7fc @prod-safe', async () => {
    await openTehilimChapter(1);
    await expect(byText('תהילים א׳')).toBeDisplayed();
    await expect(byTextContains('אשרי האיש אשר')).toBeDisplayed();
    const src = (await driver.getPageSource()).normalize('NFC');
    expect(/[ְ-ּ]/.test(src)).toBe(true);                      // ניקוד есть
    expect(src.includes('אַשְׁרֵי'.normalize('NFC')) || /א[֑-ׇ]+ש[֑-ׇ]+ר[֑-ׇ]*י/.test(src)).toBe(true);
  });

  it('TH-04c AC2 «סיים קריאה» в א׳ → «הקריאה הושלמה», «סיימת את תהילים א׳.» #6a86f7fc @data', async () => {
    // @data: отметка о прочтении пишется в аккаунт и НЕ убирается (возврата нет и не требуется — D-06). Записать в test_data прогона.
    await openTehilimChapter(1);
    await (await scrollToText('סיים קריאה', 15)).click();
    await expect(byTextContains('הקריאה הושלמה')).toBeDisplayed({ wait: 10000 });
    await expect(byTextContains('סיימת את תהילים א׳.')).toBeDisplayed();
  });

  it('TH-04d AC4 Пустая глава ל״ט: в списке «— אין עדיין טקסט», в главе «לפרק הזה עדיין אין טקסט.», «לרשימת הפרקים» #6a86f7fc @data @manual-check', async function () {
    const allowPrep = process.env.QA_ALLOW_TEHILIM39_EMPTY === '1';
    let prepared = false;
    try {
      if (!(await t39IsEmptyInList())) {
        if (!allowPrep) skipWith(this, 'ל״ט с текстом — подготовить пустую главу вручную (шаги в шапке) или QA_ALLOW_TEHILIM39_EMPTY=1; ПОТОМ ВЕРНУТЬ ТЕКСТ');
        // Подготовка (прод!): очистить текст ל״ט и опубликовать.
        await asAdmin();
        await openAdminT39Section();
        await setBody('');
        await saveDraft();
        prepared = true;
        await approveDraft(qaMarker('th04-empty'));
        expect(await t39IsEmptyInList()).toBe(true);
      }
      // Список: label «תהילים ל״ט — אין עדיין טקסט».
      const item = await byLabelStartsWith(T39_EMPTY_LABEL);
      await expect(item).toBeDisplayed();
      await item.click();
      // Глава: «לפרק הזה עדיין אין טקסט.» и «לרשימת הפרקים» → обратно к списку.
      await expect(byTextContains(T39_EMPTY_READER)).toBeDisplayed({ wait: 15000 });
      await tapText('לרשימת הפרקים');
      await expect(byText('פרקי אבות')).toBeDisplayed({ wait: 10000 });
    } finally {
      if (prepared) {
        // ⚠ Вернуть оригинал посимвольно.
        try {
          const orig = origT39();
          await toHome();
          await openAdminT39Section();
          await setBody(orig);
          await saveDraft();
          await approveDraft(qaMarker('th04-restore'));
          await toHome();
          await openAdminT39Section();
          const now = await readBody();
          if (now !== orig) throw new Error(`ל״ט не вернулся посимвольно: ${now.length} симв. против ${orig.length} — ВЕРНУТЬ ВРУЧНУЮ из orig-tehilim-39.txt`);
        } finally {
          await backToUser1();
        }
      }
    }
  });

  it('TH-04e ל״ט после AC4: текст на месте и совпадает с orig-tehilim-39.txt посимвольно (админка, без изменений) #6a86f7fc @prod-safe', async () => {
    try {
      expect(await t39IsEmptyInList()).toBe(false);
      await asAdmin();
      await openAdminT39Section();
      expect(await readBody()).toBe(origT39());
    } finally {
      await backToUser1();
    }
  });
});
